-/**
- * Bounded retry for RELEASE (issue #66). Deliberately much shorter than the
- * acquisition budget above: acquisition waits out CONTENTION (another process
- * inside its critical section, which can legitimately take seconds), whereas
- * release waits out a TRANSIENT HANDLE — an AV scanner or the Windows indexer
- * that opened the lock directory a moment ago and clears in milliseconds.
- *
- * Four sleeps of `RELEASE_RETRY_MS` is a worst case well under a tenth of
- * `DEFAULT_RETRY_MS`'s own acquisition window, and the common case — a clean
- * `rmdirSync` on the first attempt — sleeps not at all.
- */
-export const RELEASE_ATTEMPTS = 5;
-export const RELEASE_RETRY_MS = 10;
-
 /** Options controlling a lock's bounded retry/backoff. */
 export interface LockOptions {
   /** Total time to keep retrying before giving up (EC-001). */
@@ -157,56 +143,6 @@ function timeoutMessage(path: string, label: string, timeoutMs: number): string
   );
 }

-/**
- * Release the lock directory at `path`: bounded-retry `rmdirSync`, then WARN.
- *
- * ONE implementation, called from both release sites, for the same reason the
- * module header gives for the locks themselves — a forked release is how the two
- * drift, and only one of them ends up retrying.
- *
- * ISSUE #66. This used to be a single `rmdirSync` in a `finally` whose `catch`
- * was empty. The comment there stated the right constraint — a failed release
- * must not mask what the critical section returned or threw, so this must never
- * throw — but it discarded the INFORMATION along with the exception, so a
- * transient failure and a permanent one were indistinguishable: silence. On
- * Windows a transient `EBUSY`/`EPERM` from an AV scanner or the indexer holding a
- * handle then stranded the directory, and the NEXT, fully sequential invocation
- * burned its whole acquisition window against a lock whose owner had already
- * exited — reported as a spurious EC-001 with zero concurrent writers.
- *
- * Retrying absorbs that. It does not make release infallible: a handle held past
- * the budget still loses, and the lock directory is still left behind (the
- * unchanged fallback the EC-001 message already documents — "remove the stale
- * lock directory"). What changes is that the failure is now audible on stderr
- * instead of invisible, and still non-fatal (EC-002).
- */
-function releaseLock(path: string, label: string): void {
-  for (let attempt = 1; ; attempt += 1) {
-    try {
-      rmdirSync(path);
-      return;
-    } catch (err) {
-      // Already gone is the goal, not a failure — and it is a REACHABLE state,
-      // because the EC-001 message tells operators to remove a stale lock
-      // directory and they can do so while its owner is still running. Retrying
-      // against it can never change the answer, and warning "could not remove;
-      // may be left behind" about a directory that is not there would be a new
-      // false alarm from the fix whose whole point is fewer of those.
-      if ((err as { code?: string } | null)?.code === "ENOENT") return;
-      if (attempt >= RELEASE_ATTEMPTS) {
-        const detail = err instanceof Error ? err.message : String(err);
-        process.stderr.write(
-          `redkiln: warning: could not remove the ${label} lock directory ${path} ` +
-            `after ${RELEASE_ATTEMPTS} attempts (${detail}). It may be left behind; ` +
-            `remove it if a later redkiln command reports EC-001 against it.\n`,
-        );
-        return;
-      }
-      sleepSync(RELEASE_RETRY_MS);
-    }
-  }
-}
-
 /**
  * Run `critical` while holding an exclusive on-disk lock, SYNCHRONOUSLY.
  *
@@ -255,9 +191,11 @@ export function withSyncLock<T>(
     return critical();
   } finally {
     held.set(path, 0);
-    // Bounded retry, then warn — never throws, so a failed rmdir cannot mask the
-    // critical section's own result/error. See `releaseLock`.
-    releaseLock(path, label);
+    try {
+      rmdirSync(path);
+    } catch {
+      // Best-effort release; a failed rmdir must not mask the result/error.
+    }
   }
 }

@@ -309,11 +247,11 @@ export async function withAsyncLock<T>(
     return await critical();
   } finally {
     held.set(path, 0);
-    // Same shared release as the sync path — see `releaseLock`. Synchronous by
-    // design: the retry budget is a few tens of milliseconds in the failing case
-    // and zero in the common one, and forking an async variant is exactly how the
-    // two paths drifted before.
-    releaseLock(path, label);
+    try {
+      rmdirSync(path);
+    } catch {
+      // Best-effort release.
+    }
   }
 }

